//------//

const init = ({ eventManager, store, playerHash, roomHash }) => {
  const liveUpdatePws = new PersistentWebsocket(liveUpdateWebsocket.url, {
      pingSendFunction: pws => pws.send('ping'),
      reachabilityTestUrl: '/ping',
